import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitivesLib from '@/primitives';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, PointLight, Color, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'quote-panel-pricing';

  const CARD_W = 2.4;
  const CARD_H = 1.4;

  // -------- contact shadow (grounded element) --------
  const shadowGeo = new PlaneGeometry(CARD_W * 1.3, CARD_H * 1.3);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color('#000000'),
    transparent: true,
    opacity: 0.45,
    depthWrite: false,
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -CARD_H * 0.62, -0.05);
  shadowMesh.rotation.x = 0;
  root.add(shadowMesh);

  // -------- accent edge frame (focus/hover indicator) --------
  const edgeGeo = new PlaneGeometry(CARD_W + 0.08, CARD_H + 0.08);
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.0,
  });
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.set(0, 0, -0.02);
  root.add(edgeMesh);

  // -------- main card plane --------
  const cardGeo = new PlaneGeometry(CARD_W, CARD_H);
  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.6,
    metalness: 0.3,
    side: DoubleSide,
  });
  cardMat.clearcoat = 0.15;
  const cardMesh = new Mesh(cardGeo, cardMat);
  root.add(cardMesh);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    cardMat.map = tex;
    cardMat.color = new Color('#ffffff');
    cardMat.needsUpdate = true;
  }).catch(() => {});

  // -------- local rim light (accent hued) --------
  const rimLight = new PointLight(new Color(colors.accent), 1.0, 4, 2);
  rimLight.position.set(-1.2, 0.6, 1.0);
  root.add(rimLight);

  // -------- decorative quote glyph (ornamental, not invented copy) --------
  const quoteGlyph = ctx.fontAtlas.createText('"', {
    fontSize: 96,
    color: colors.accent,
    align: 'left',
  });
  quoteGlyph.position.set(-CARD_W * 0.42, CARD_H * 0.28, 0.01);
  root.add(quoteGlyph);

  // -------- primitives --------
  const primitiveResults = [];
  const primitiveSpecs = config.cinematicPrimitives ?? [];
  for (const p of primitiveSpecs) {
    const fn = ctx.primitives[p.name];
    if (typeof fn === 'function') {
      const res = fn(root, p.params ?? {});
      if (res) primitiveResults.push(res);
    }
  }

  // -------- interaction state / gsap --------
  const timelines = [];
  let hovered = false;

  function hoverIn() {
    if (hovered) return;
    hovered = true;
    const tl = gsap.timeline();
    tl.to(root.position, { y: '+=0.15', duration: 0.5, ease: 'power3.out' }, 0);
    tl.to(edgeMat, { opacity: 0.6, duration: 0.3, ease: 'power2.out' }, 0);
    tl.to(cardMesh.scale, { x: 1.02, y: 1.02, z: 1.02, duration: 0.5, ease: 'power3.out' }, 0);
    timelines.push(tl);
  }

  function hoverOut() {
    if (!hovered) return;
    hovered = false;
    const tl = gsap.timeline();
    tl.to(root.position, { y: '-=0.15', duration: 0.5, ease: 'power3.out' }, 0);
    tl.to(edgeMat, { opacity: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
    tl.to(cardMesh.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power3.out' }, 0);
    timelines.push(tl);
  }

  function pressDown() {
    const tl = gsap.timeline();
    tl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    timelines.push(tl);
  }

  function pressUp() {
    const tl = gsap.timeline();
    tl.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power2.out' });
    timelines.push(tl);
  }

  function onClick() {
    pressDown();
    gsap.delayedCall(0.12, pressUp);
    ctx.emit('hub-pricing.select', { source: 'quote-panel', node: root.name });
  }

  // entrance settle
  root.scale.set(0.96, 0.96, 0.96);
  const entranceTl = gsap.timeline();
  entranceTl.to(root.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(entranceTl);

  root.userData.handlers = {
    pointerenter: hoverIn,
    pointerleave: hoverOut,
    pointerdown: pressDown,
    pointerup: pressUp,
    click: onClick,
  };

  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const res of primitiveResults) {
      if (res && typeof res.cleanup === 'function') res.cleanup();
    }
    shadowGeo.dispose();
    shadowMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    if (cardMat.map) cardMat.map.dispose();
    if (quoteGlyph.userData?.cleanup) quoteGlyph.userData.cleanup();
  };

  return root;
}
